values ('bacc1020-2014-4200-8000-000000000001', 'អត្ថបទគំរូ (AI)៖ អក្សរសាស្ត្រជាព្រលឹង និងអត្តសញ្ញាណជាតិ៖ ពេលអក្សរសាស្ត្រធ្លាក់ចុះ ជាតិក៏ទន់ខ្សោយ ពេលអក្សរសាស្ត្ររីកចម្រើន ជាតិក៏រុងរឿង។ ឧទាហរណ៍៖ អក្សរសិល្ប៍សម័យអង្គរ (រាមកេរ្តិ៍) សម័យអាណានិគម (ភូមិតិរច្ឆាន) និងសម័យឯករាជ្យ (ព្រះអាទិត្យថ្មីរះលើផែនដីចាស់)។ ចុច «Show the working» ដើម្បីអានទាំងស្រុង។', null, null, null, '[{"content":"ទម្រង់៖ សេចក្តីផ្តើម (លំនាំ ចំណូល ចំណោទបញ្ហា) · តួសេចក្តី (ពន្យល់ពាក្យ ពន្យល់ន័យ បំណកស្រាយ ឧទាហរណ៍បីរឿង សរុបមតិ) · សេចក្តីបញ្ចប់ (វាយតម្លៃ និងមតិផ្ទាល់ខ្លួន)។"},{"content":"សេចក្តីផ្តើម៖ ភាសា និងអក្សរសាស្ត្រ គឺជាកេរដំណែលដ៏មានតម្លៃរបស់ជាតិនីមួយៗ។ ហេតុនេះមានទស្សនៈថា «អក្សរសាស្ត្ររលត់ ជាតិរលាយ អក្សរសាស្ត្រពណ្ណរាយ ជាតិថ្កើងថ្កាន»។ តើទស្សនៈនេះមានន័យដូចម្តេច?"},{"content":"ពន្យល់ពាក្យ និងន័យ៖ អក្សរសាស្ត្រ គឺភាសា អក្សរ និងស្នាដៃសរសេរនៃជាតិ។ រលត់ គឺបាត់បង់ ឬធ្លាក់ចុះ។ រលាយ គឺវិនាស បាត់អត្តសញ្ញាណ។ ពណ្ណរាយ គឺរីកចម្រើន ភ្លឺស្វាង។ ថ្កើងថ្កាន គឺរុងរឿង។ ទស្សនៈនេះមានន័យថា ជោគវាសនានៃជាតិ ភ្ជាប់ជាមួយជោគវាសនានៃអក្សរសាស្ត្ររបស់ខ្លួន។"},{"content":"បំណកស្រាយ៖ អក្សរសាស្ត្រជាមូលដ្ឋានទ្រទ្រង់ជាតិ ជាព្រលឹង និងអត្តសញ្ញាណ ជាមធ្យោបាយទំនាក់ទំនង និងអប់រំកូនចៅ។ ពេលអក្សរសាស្ត្រត្រូវគេមើលងាយ ឬបំបាត់ ជាតិក៏បាត់អត្តសញ្ញាណ វប្បធម៌ និងឯករាជ្យ។ ផ្ទុយទៅវិញ ពេលអក្សរសាស្ត្ររីកចម្រើន ប្រទេសមានឯករាជ្យ កិត្យានុភាព និងការរីកចម្រើន។"},{"content":"ឧទាហរណ៍ទី១៖ សម័យអង្គរ៖ អក្សរសាស្ត្រខ្មែររុងរឿង មានសិលាចារឹក និងស្នាដៃដូចរឿងរាមកេរ្តិ៍ ស្របពេលដែលអាណាចក្រខ្មែររុងរឿងបំផុតក្នុងតំបន់។"},{"content":"ឧទាហរណ៍ទី២៖ សម័យអាណានិគមបារាំង៖ ភាសាបារាំងជាភាសាផ្លូវការ ភាសាខ្មែរត្រូវមើលងាយ ហើយប្រទេសជាតិស្ថិតក្រោមការត្រួតត្រា។ រឿងភូមិតិរច្ឆាន៖ បង្ហាញពីទុក្ខវេទនារបស់ប្រជាជនខ្មែរ ក្រោមការជិះជាន់ និងការប្រើអំណាចផ្តាច់ការ នៅសម័យអាណានិគមបារាំង។ រឿងនេះជាកញ្ចក់ឆ្លុះបញ្ចាំងពីភាពអយុត្តិធម៌ក្នុងសង្គមនោះ។"},{"content":"ឧទាហរណ៍ទី៣៖ សម័យឯករាជ្យ (១៩៥៣–១៩៧០)៖ ភាសាខ្មែរបានក្លាយជាភាសាផ្លូវការ អក្សរសិល្ប៍ខេមរៈរីកចម្រើន ហើយប្រទេសក៏រីកចម្រើន។ រឿងព្រះអាទិត្យថ្មីរះលើផែនដីចាស់ (សួន សុរិន)៖ បង្ហាញពីសង្គមខ្មែរក្រោយឯករាជ្យ ដែលមនុស្សខិតខំសិក្សា ធ្វើការ និងបម្រើជាតិ ដើម្បីកសាងប្រទេសឲ្យរីកចម្រើន។"},{"content":"សរុបមតិ៖ ប្រវត្តិសាស្ត្របង្ហាញថា ភាពរុងរឿង ឬអន់ថយនៃជាតិ ដើរស្របគ្នាជាមួយភាពរុងរឿង ឬអន់ថយនៃអក្សរសាស្ត្រជាតិ។"},{"content":"សេចក្តីបញ្ចប់៖ ទស្សនៈនេះពិតជាមានអត្ថន័យជ្រាលជ្រៅ។ ក្នុងនាមជាកូនខ្មែរ យើងត្រូវស្រឡាញ់ សិក្សា ប្រើប្រាស់ឲ្យត្រឹមត្រូវ និងថែរក្សាភាសា និងអក្សរសាស្ត្រជាតិ ឲ្យគង់វង្សយូរអង្វែង។"},{"content":"ចំណាំ៖ នេះជាអត្ថបទគំរូមួយក្នុងចំណោមចម្លើយល្អៗជាច្រើន។ សិស្សអាចលើករឿងផ្សេងទៀតដែលបានរៀន ឲ្យតែត្រូវនឹងប្រធាន ហើយគួរផ្ទៀងផ្ទាត់ឈ្មោះតួអង្គ និងអ្នកនិពន្ធជាមួយសៀវភៅសិក្សា។"}]'::jsonb, 'ai-generated', 'Answer key written by AI (Claude) for Meh Rean from the typed question; not checked by a teacher.', 'needs-review')
on conflict (question_id) do update set answer = excluded.answer, steps = excluded.steps, source = excluded.source
  where public.question_solutions.origin = 'ai-generated' and public.question_solutions.verification <> 'verified';

insert into public.exam_papers (id, subject_id, year, title_en, title_km, duration_minutes, duration_source, origin, source, verification)
values ('bacc1020-2014-4100-8000-000000000000', 'kh-grade12-science-khmer-literature', 2014, 'BacII 2014, first sitting: Khmer literature (science track)', 'វិញ្ញាសាអក្សរសាស្ត្រខ្មែរ បាក់ឌុបឆ្នាំ២០១៤ លើកទី១ (ថ្នាក់វិទ្យាសាស្ត្រ)', 90, 'Printed on the paper: រយៈពេល ៩០ នាទី', 'official', 'BacII 2014, first sitting (2014-08-04), science track khmer literature, Ministry of Education, Youth and Sport. Typed by Meh Rean from one copy: retyped by ជៀប គន្ធា (github.com/HELMAB/bacii). Not yet checked against the Ministry''s original.', 'needs-review')
on conflict (id) do update set title_en = excluded.title_en, title_km = excluded.title_km, duration_minutes = excluded.duration_minutes,
  duration_source = excluded.duration_source, source = excluded.source;

insert into public.questions (id, chapter_id, topic_id, year, type, content, choices, images, difficulty, language, origin, source, verification)
values ('bacc1020-2014-4100-8000-000000000001', 'kh-grade12-science-khmer-literature-past-papers', null, 2014, 'open', 'មានទស្សនៈមួយចែងថា៖ «អក្សរសិល្ប៍គឺជាកញ្ចក់សម្រាប់ឆ្លុះសង្គម»។ ចូរអ្នកធ្វើការបកស្រាយទស្សនៈនេះ ដោយរកឧទាហរណ៍ក្នុងអក្សរសិល្ប៍ខ្មែរមកបញ្ជាក់។', '[]'::jsonb, '[]'::jsonb, null, 'km', 'official-past-paper', 'BacII 2014, first sitting (2014-08-04), science track khmer literature, Ministry of Education, Youth and Sport. Typed by Meh Rean from one copy: retyped by ជៀប គន្ធា (github.com/HELMAB/bacii). Not yet checked against the Ministry''s original.', 'needs-review')
on conflict (id) do update set chapter_id = excluded.chapter_id, content = excluded.content, images = excluded.images, language = excluded.language, source = excluded.source;
