values ('bacc1010-2024-4000-8000-000000000004', 'kh-grade12-science-mathematics-complex-numbers', null, 2024, 'open', 'នៅក្នុងសំណុំនៃចំនួនកុំផ្លិច $\mathbb{C}$។
